 if(s==='fan'&&!queen.shot){queen.shot=true;const a=Math.atan2(queen.target.y-boss.y,queen.target.x-boss.x),n=queen.phase===1?5:7;for(let i=0;i<n;i++){if(i===Math.floor(n/2))continue;const angle=a+(i-(n-1)/2)*.23;projectiles.push({x:boss.x-60,y:boss.y-45,vx:Math.cos(angle)*(250+queen.phase*20),vy:Math.sin(angle)*(250+queen.phase*20),type:'royal-pearl',queenOwned:true,variant:queen.phase>1?'sine':'straight',phase:i,age:0,life:4,hitRadius:30});}}
