 for(const c of palace.curtains){const x=c.x-camera;if(x<-120||x>vw+120)continue;ctx.save();const reveal=Math.abs(nessie.x-c.x)<180;ctx.globalAlpha=reveal?.17:.65;ctx.strokeStyle='#719d9f';ctx.lineWidth=7;for(let i=0;i<11;i++){ctx.beginPath();ctx.moveTo(x-70+i*14,c.y);ctx.bezierCurveTo(x-70+i*14+Math.sin(tick-i*.15)*18,c.y+110,x-70+i*14-Math.sin(tick*.7-i*.2)*15,c.y+230,x-70+i*14,c.y+325);ctx.stroke();}ctx.restore();}
