function drawFamilyBarrier(o,x,t){if(releaseFamilyBarrier(o,x,t))return;ctx.save();ctx.translate(x,o.y);if(o.trainingRock){const g=ctx.createLinearGradient(0,0,o.w,o.h);g.addColorStop(0,'#9bbcc5');g.addColorStop(.5,'#668eaa');g.addColorStop(1,'#476785');ctx.fillStyle=g;ctx.strokeStyle='#bbd9de';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,o.h);ctx.quadraticCurveTo(-20,o.h*.5,30,24);ctx.quadraticCurveTo(o.w*.5,-10,o.w-20,35);ctx.quadraticCurveTo(o.w+15,o.h*.5,o.w,o.h);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle='#fff0b2';ctx.lineWidth=2;ctx.beginPath();ctx.arc(o.w*.5,o.h*.5,24,.2,Math.PI*1.8);ctx.stroke();ctx.fillStyle='#d9e9e8';ctx.font='900 13px Nunito,sans-serif';ctx.textAlign='center';ctx.fillText('ELITE',o.w*.5,o.h*.5+4);}else if(o.trainingJump){ctx.fillStyle='#8bbab7';ctx.strokeStyle='#d9efe2';ctx.lineWidth=3;ctx.beginPath();ctx.roundRect(0,0,o.w,o.h,22);ctx.fill();ctx.stroke();for(let i=0;i<4;i++){ctx.strokeStyle='#b4ead5';ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(20+i*17,o.h);ctx.bezierCurveTo(10+i*17,o.h*.6,32+i*17,o.h*.4,20+i*17,15);ctx.stroke();}}else if(!o.gate){drawRoyalColumn(o.w*.5,0,o.w,o.h,t,true);ctx.fillStyle='#daa5b9';for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse(o.w*.5+Math.cos(i*1.3)*o.w*.4,10,28,12,i*.7,0,Math.PI*2);ctx.fill();}}ctx.restore();}
function drawFamilyForeground(t){if(releaseFamilyForeground(t))return;ctx.save();for(let i=0;i<18;i++){const x=140+i*220-camera;if(x<-150||x>vw+150)continue;const y=935;ctx.strokeStyle=isTraining()?'#7ac8b4':'#c99bb5';ctx.lineWidth=8;for(let j=0;j<3;j++){ctx.beginPath();ctx.moveTo(x+j*12,y);ctx.bezierCurveTo(x+j*12+Math.sin(t*.6+i+j)*8,y-25,x+j*12-12,y-55,x+j*12,y-65-j*8);ctx.stroke();}ctx.fillStyle=isTraining()?'#f0d297':'#edcfbd';ctx.beginPath();ctx.ellipse(x+16,y-5,45,17,0,Math.PI,Math.PI*2);ctx.fill();}if(isPalace()){ctx.strokeStyle='#e6ceb72a';ctx.lineWidth=2;for(let i=0;i<30;i++){const x=i*155-camera;ctx.beginPath();ctx.moveTo(x,960);ctx.lineTo(x+110,880);ctx.stroke();}}ctx.restore();}
function drawFamilyProjectile(p,t){if(!['royal-pearl','training-bolt'].includes(p.type))return false;const x=p.x-camera,y=p.y;if(x<-80||x>vw+80)return true;drawSpellWake(p,t);ctx.save();ctx.translate(x,y);if(p.type==='royal-pearl'){const g=ctx.createRadialGradient(-5,-5,1,0,0,17);g.addColorStop(0,'#fffef4');g.addColorStop(.35,'#f9e5d7');g.addColorStop(.65,'#b7c5e5');g.addColorStop(1,'#d6acd0');ctx.fillStyle=g;ctx.strokeStyle='#fff0d8';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,16,0,Math.PI*2);ctx.fill();ctx.stroke();ellipse(-5,-5,4,3,'#ffffffd9');ctx.strokeStyle='#f6dcb76b';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-p.vx*.08,-p.vy*.08);ctx.lineTo(0,0);ctx.stroke();}else{ctx.rotate(Math.atan2(p.vy,p.vx)+Math.PI/2);ctx.strokeStyle='#ffe9a8';ctx.fillStyle='#fff5cf';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-4,-24);ctx.lineTo(-15,2);ctx.lineTo(-2,0);ctx.lineTo(-8,23);ctx.lineTo(16,-5);ctx.lineTo(4,-3);ctx.closePath();ctx.fill();ctx.stroke();}ctx.restore();return true;}
function updateFamilyHud(){const active=isTraining()||isPalace();$('boss-hud').classList.toggle('family-fight',active);$('boss-hud').classList.toggle('queen-fight',isPalace());if(!active)return;if(isTraining()&&training&&training.step>=0&&training.step<6){const goal=trainingGoal();setHtmlIfChanged($('coin-progress'),cueMarkup(training.step===2?'boost':training.step===3||training.step===4?'leap':training.step===5?'heart':'compass')+'<small>'+Math.min(7,training.step+1)+' / 7</small>');$('coin-progress').setAttribute('aria-label','Training trial '+(training.step+1)+' of 7');$('coin-progress-fill').style.width=training.step/7*100+'%';$('objective-label').textContent=['Follow the rings','Swim around the reef','Try a boost','Leap above the waves','Clear the reef','Collect both gifts','The final trial'][training.step];}if(!boss?.active)return;if(isTraining())$('boss-name').textContent='King Daddy · Thunder & Bedtime';if(isPalace())$('boss-name').textContent='Queen Antonella · The Pearl Queen';if(boss.hp>0){const charge=isTraining()?boss.clock%10<2.6:queen?.state.endsWith('Charge');setIconCue($('boss-cue'),boss.vulnerable?'boost':charge?'warning':'shield',boss.vulnerable?'Green opening: boost now':charge?'A royal attack is preparing':'Wait for the green opening');}}
function cueMarkup(icon){return '<svg class="cue-icon" aria-hidden="true"><use href="#cue-'+icon+'"></use></svg>';}
function installFamilyDialogue(){const c=(speaker,portrait,line,options)=>({speaker,portrait,line,options,hint:''});Object.assign(conversations,{
'daddy-intro':c('King Daddy','daddy-heroic','Sarah! The hour has come!',[['For what?','Training.\nSarah: You could have just said that.'],['Am I in trouble?','Never. …Unless your mother asks.'],['Can Nessie come?','Of course.\nNessie: Do I get armour?\nKing Daddy: No.\n(A tiny helmet appears anyway.)']]),
'daddy-rock':c('King Daddy','daddy-serious','Behold. The rock.',[['It’s a rock.','An elite rock.'],['Does it have a health bar?','Not yet. It is still negotiating its contract.']]),
'daddy-trial':c('King Daddy','daddy-heroic','Your final trial!',[['Are we actually fighting?','Training fight.\nSarah: Okay.\nKing Daddy: BUT SAY IT WITH MORE DRAMA.'],['Your cloud looks friendly.','FEAR THE CLOUD!\nSarah: It likes me.\nKing Daddy: No it doesn’t.']]),
'daddy-win':c('King Daddy','daddy-warm','You have completed the ancient trials.\nSarah: I swam around a rock.\nKing Daddy: An elite rock.',[['Thanks, Dad.','Anytime, little mermaid. Go get ’em.'],['Can I have the lightning staff?','No. …Your mother would kill me.'],['Was that actually a boss fight?','I had a health bar.\nSarah: Fair.']]),
'queen-arrival':c('Queen Antonella','queen-unimpressed','Sarah Maria. You cannot go to Rainbow Ruin. You have not passed the Royal Mermaid Test.',[['I defeated a crab and a manta ray!','Yes. But have you passed the Royal Mermaid Test?\nSarah: The what?\nAntonella: Exactly.'],['Dad said I was ready.','Your father considers swimming around a rock advanced combat training.'],['Your palace is beautiful.','Thank you, darling. Try not to boost through the chandeliers.']]),
'royal-guard':c('Sir Seahorse','royal-guard','Her Majesty requests your presence.',[['Am I in trouble?','That depends on how your mother defines trouble.'],['Can I just swim past?','You could. …No.'],['Is Dad involved?','Not officially. We are still removing thunderclouds from the curtains.']]),
'queen-boss':c('Queen Antonella','queen-competitive','One final test.\nSarah: I knew you were going to say that.',[['Ready, Mum!','Good. Precision, poise, and absolutely no starfish in the jewellery.'],['Did Dad help design this?','He proposed a second rock. I declined.'],['Is that your good crown?','They are ALL my good crowns, Sarah Maria.']]),
'queen-win':c('Queen Antonella','queen-proud','Fine. You may proceed.\nSarah: That’s it?\nAntonella: Would you like another phase?\nSarah: No.',[['Thanks, Mum.','You did wonderfully. …I knew you would.\nBe careful. The frog is completely ridiculous. Dangerous? That too.'],['Was all of that necessary?','No. …But it was fabulous.'],['Dad’s tutorial was easier.','Your father considers a rock advanced combat training.\nKing Daddy: IT WAS AN ELITE ROCK.\nAntonella: Goodbye, Sam.']])
});conversations.final.line='The gold is safe, the lagoon is free, and Sarah has passed Mum’s fabulous royal test. Three cheers for Sarah Maria!';}
